package com.sumaye.restaurant.service; import com.sumaye.restaurant.dto.*; import com.sumaye.restaurant.exception.*; import com.sumaye.restaurant.model.*; import com.sumaye.restaurant.repository.*; import lombok.RequiredArgsConstructor; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.time.*; import java.util.*;
@Service @RequiredArgsConstructor public class ReservationService {private final ReservationRepository reservations;private final BranchRepository branches;private final CustomerRepository customers;private final RestaurantTableRepository tables;private final UserRepository users; private final org.springframework.messaging.simp.SimpMessagingTemplate messaging;
 @Transactional public Reservation create(Long branchId,ReservationRequest r,String username){if(!r.getEndTime().isAfter(r.getStartTime()))throw new ApiException("Muda wa kuondoka lazima uwe baada ya muda wa kuanza");if(r.getReservationDate().equals(LocalDate.now())&&!r.getStartTime().isAfter(LocalTime.now()))throw new ApiException("Muda wa kuanza lazima uwe wa baadaye");Branch b=branches.findById(branchId).orElseThrow(()->new ResourceNotFoundException("Tawi halikupatikana"));RestaurantTable t=tables.findById(r.getTableId()).orElseThrow(()->new ResourceNotFoundException("Meza haikupatikana"));if(!t.getBranch().getId().equals(branchId)||t.getCapacity()<r.getGuestCount())throw new ApiException("Meza haipatikani kwa idadi hii ya watu");if(!reservations.overlaps(t.getId(),r.getReservationDate(),r.getStartTime(),r.getEndTime()).isEmpty())throw new ApiException("Meza hii tayari imehifadhiwa kwa muda huo");Customer c=customers.findById(r.getCustomerId()).orElseThrow(()->new ResourceNotFoundException("Mteja hakupatikana"));if(!c.isActive()||!c.getRestaurant().getId().equals(b.getRestaurant().getId()))throw new ApiException("Mteja si halali kwa mgahawa huu");Reservation x=new Reservation();x.setBranch(b);x.setCustomer(c);x.setTable(t);x.setReservationDate(r.getReservationDate());x.setStartTime(r.getStartTime());x.setEndTime(r.getEndTime());x.setGuestCount(r.getGuestCount());x.setNotes(r.getNotes());x.setCreatedBy(users.findByUsername(username).orElseThrow(()->new ResourceNotFoundException("Mtumiaji hakupatikana")));return reservations.save(x);}
 @Transactional(readOnly=true) public List<Reservation> today(Long b,LocalDate d){if(!branches.existsById(b))throw new ResourceNotFoundException("Tawi halikupatikana");return reservations.findByBranchIdAndReservationDateOrderByStartTime(b,d);}
 @Transactional public Reservation status(Long branchId,Long id,Reservation.Status status){Reservation r=reservations.findById(id).orElseThrow(()->new ResourceNotFoundException("Uhifadhi haukupatikana"));if(!r.getBranch().getId().equals(branchId))throw new ResourceNotFoundException("Uhifadhi haukupatikana");if(r.getStatus()==Reservation.Status.CANCELLED||r.getStatus()==Reservation.Status.COMPLETED||r.getStatus()==Reservation.Status.NO_SHOW)throw new ApiException("Uhifadhi huu hauwezi kubadilishwa tena");if(!canTransition(r.getStatus(),status))throw new ApiException("Hatua ya uhifadhi si sahihi");r.setStatus(status);r.setUpdatedAt(LocalDateTime.now());if(status==Reservation.Status.SEATED){r.getTable().setStatus(RestaurantTable.TableStatus.OCCUPIED);r.getTable().setUpdatedAt(LocalDateTime.now());}if(status==Reservation.Status.CANCELLED||status==Reservation.Status.COMPLETED||status==Reservation.Status.NO_SHOW){r.getTable().setStatus(RestaurantTable.TableStatus.AVAILABLE);r.getTable().setUpdatedAt(LocalDateTime.now());}Reservation saved=reservations.save(r);messaging.convertAndSend("/topic/branches/"+r.getBranch().getId()+"/reservations",saved);return saved;}
 private boolean canTransition(Reservation.Status from,Reservation.Status to){if(from==to)return true;return switch(from){case PENDING->to==Reservation.Status.CONFIRMED||to==Reservation.Status.CANCELLED;case CONFIRMED->to==Reservation.Status.SEATED||to==Reservation.Status.CANCELLED||to==Reservation.Status.NO_SHOW;case SEATED->to==Reservation.Status.COMPLETED;default->false;};}}
